package pe.edu.upeu.inscripcion.service;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.math.BigDecimal;import java.time.LocalDateTime;import java.util.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;
import pe.edu.upeu.inscripcion.entity.*;import pe.edu.upeu.inscripcion.repository.*;import pe.edu.upeu.inscripcion.mapper.InscripcionMapper;import pe.edu.upeu.inscripcion.messaging.AcademicoEventosProducer;import pe.edu.upeu.inscripcion.client.CertificadoContextoClient;import pe.edu.upeu.inscripcion.dto.*;
@ExtendWith(MockitoExtension.class)class CertificadoEmisionTest {
 @Mock InscripcionRepository repository;@Mock AsistenciaRepository asistenciaRepo;@Mock CertificadoRepository certificadoRepo;@Mock InscripcionMapper mapper;@Mock AcademicoEventosProducer eventos;@Mock CertificadoContextoClient contexto;@InjectMocks InscripcionService service;Inscripcion i;
 @BeforeEach void setup(){i=new Inscripcion();i.setId(24L);i.setEstudianteId(1001L);i.setCursoId(3L);i.setEstado(Inscripcion.EstadoInscripcion.ACTIVA);i.setTipoAcceso(Inscripcion.TipoAcceso.GRATUITO);i.setCertificadoHabilitado(true);i.setProgresoMinimo(100);i.setAsistenciaMinima(0);var p=new ProgresoLeccion();p.setLeccionId(6L);p.setInscripcion(i);i.getProgresos().add(p);lenient().when(repository.bloquear(24L)).thenReturn(Optional.of(i));lenient().when(certificadoRepo.save(any())).thenAnswer(x->x.getArgument(0));}
 @Test void ultimaLeccionEmiteCertificadoAutomaticamente(){service.completarLeccion(24L,6L);assertEquals(Inscripcion.EstadoInscripcion.COMPLETADA,i.getEstado());var cap=ArgumentCaptor.forClass(Certificado.class);verify(certificadoRepo).save(cap.capture());assertEquals(Certificado.EstadoCertificado.DISPONIBLE,cap.getValue().getEstado());assertTrue(cap.getValue().isPagoConfirmado());assertNotNull(cap.getValue().getFechaEmision());assertEquals(0,cap.getValue().getFechaEmision().getNano()%1000);}
 @Test void emisionConCostoEsPendienteHastaPago(){i.setCertificadoCosto(new BigDecimal("5.00"));service.completarLeccion(24L,6L);var cap=ArgumentCaptor.forClass(Certificado.class);verify(certificadoRepo).save(cap.capture());assertEquals(Certificado.EstadoCertificado.PENDIENTE_PAGO,cap.getValue().getEstado());assertFalse(cap.getValue().isPagoConfirmado());assertNull(cap.getValue().getFechaEmision());}
 @Test void descargarRepetidamenteNoCambiaCodigoNiFecha(){i.getProgresos().getFirst().setCompletada(true);var c=new Certificado();c.setInscripcionId(24L);c.setCodigo("KIDO-CERT-24-estable");c.setCosto(BigDecimal.ZERO);c.setEstado(Certificado.EstadoCertificado.DISPONIBLE);c.setPagoConfirmado(true);c.setFechaEmision(LocalDateTime.of(2026,10,27,18,0));when(certificadoRepo.findByInscripcionId(24L)).thenReturn(Optional.of(c));var primero=service.certificado(24L);var segundo=service.solicitarCertificado(24L);assertEquals(primero.codigo(),segundo.codigo());assertEquals(primero.fechaEmision(),segundo.fechaEmision());verify(certificadoRepo,never()).save(any());}
 @Test void sinCompletarNoEmite(){assertThrows(IllegalStateException.class,()->service.solicitarCertificado(24L));verify(certificadoRepo,never()).save(any());}
 @Test void inscripcionRevocadaNoEmite(){i.setEstado(Inscripcion.EstadoInscripcion.REVOCADA);i.getProgresos().getFirst().setCompletada(true);assertThrows(IllegalStateException.class,()->service.solicitarCertificado(24L));verify(certificadoRepo,never()).save(any());}
 @Test void asistenciaInsuficienteNoEmite(){i.getProgresos().getFirst().setCompletada(true);i.setAsistenciaMinima(80);when(asistenciaRepo.countByInscripcionId(24L)).thenReturn(1L);assertThrows(IllegalStateException.class,()->service.solicitarCertificado(24L));verify(certificadoRepo,never()).save(any());}
 @Test void noConfirmaPagoConRequisitosPendientes(){assertThrows(IllegalStateException.class,()->service.confirmarPagoCertificado(24L));verify(certificadoRepo,never()).save(any());}
 @Test void reglasDeInscripcionVienenDelServidor(){when(contexto.curso(3L)).thenReturn(new CertificadoContextoClient.Curso(3L,"Python","GRATUITO","PUBLICADO",1000L,List.of(6L),100,0,true,BigDecimal.ZERO));when(repository.save(any())).thenAnswer(x->x.getArgument(0));service.crear(new InscripcionRequest(1001L,3L,"GRATUITO",List.of(999L),0,0,true,BigDecimal.ZERO));var cap=ArgumentCaptor.forClass(Inscripcion.class);verify(repository).save(cap.capture());assertEquals(100,cap.getValue().getProgresoMinimo());assertEquals(6L,cap.getValue().getProgresos().getFirst().getLeccionId());}
 @Test void certificadoConCostoSeHabilitaSoloAlConfirmarPagoValido(){i.getProgresos().getFirst().setCompletada(true);i.setCertificadoCosto(new BigDecimal("5.00"));var c=new Certificado();c.setInscripcionId(24L);c.setCodigo("KIDO-CERT-24-estable");c.setCosto(new BigDecimal("5.00"));c.setEstado(Certificado.EstadoCertificado.PENDIENTE_PAGO);when(certificadoRepo.findByInscripcionId(24L)).thenReturn(Optional.of(c));var primero=service.confirmarPagoCertificado(24L);assertEquals("DISPONIBLE",primero.estado());assertTrue(primero.pagoConfirmado());assertNotNull(primero.fechaEmision());var segundo=service.confirmarPagoCertificado(24L);assertEquals(primero.fechaEmision(),segundo.fechaEmision());verify(certificadoRepo,times(1)).save(c);}
}
